"""Detect a Negative Cycle with Floyd-Warshall — check the diagonal.

Time: O(n^3)   Space: O(n^2)
"""
from typing import List


class Solution:
    def hasNegativeCycleFW(self, n: int, edges: List[List[int]]) -> bool:
        INF = float("inf")
        dist = [[0 if i == j else INF for j in range(n)] for i in range(n)]
        for u, v, w in edges:
            dist[u][v] = min(dist[u][v], w)

        for k in range(n):
            for i in range(n):
                if dist[i][k] == INF:
                    continue
                for j in range(n):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        return any(dist[i][i] < 0 for i in range(n))
